<?php
namespace App\Http\Controllers\Admin; use App\Enums\InstallationStatus; use App\Http\Controllers\Controller; use App\Http\Requests\InstanceRequest; use App\Models\{Client,IkontrolInstance,InstanceInstallationLog}; use App\Services\{AuditService,IkontrolInstanceConnectionService,IkontrolInstanceInspectorService};
class InstanceController extends Controller { public function index(){return view('admin.instances.index',['instances'=>IkontrolInstance::with('client')->latest()->paginate(20)]);} public function create(){return view('admin.instances.register',['clients'=>Client::whereActive(true)->orderBy('name')->get()]);} public function store(InstanceRequest $r,AuditService $a){$d=$r->validated();$i=IkontrolInstance::create($d+['absolute_path'=>rtrim(config('ikontrol.instances_root'),'/\\').DIRECTORY_SEPARATOR.$d['folder_name'],'db_host'=>config('ikontrol.db.host'),'db_port'=>config('ikontrol.db.port'),'installation_status'=>InstallationStatus::Ready,'active'=>true]);InstanceInstallationLog::create(['instance_id'=>$i->id,'step'=>'REGISTERING','status'=>'SUCCESS','message'=>'Instalación existente registrada manualmente.','created_at'=>now()]);$a->record('register_instance','Instalación existente registrada.',$i);return redirect()->route('instances.show',$i)->with('success','Instalación registrada.');} public function show(IkontrolInstance $instance){$instance->load(['client','installationLogs','latestInspection']);return view('admin.instances.show',compact('instance'));} public function testConnection(IkontrolInstance $instance,IkontrolInstanceConnectionService $s,AuditService $a){$r=$s->test($instance);$a->record('test_connection','Prueba de conexión ejecutada.',$instance,['success'=>$r['success']]);return back()->with($r['success']?'success':'error',$r['message']);} public function inspect(IkontrolInstance $instance,IkontrolInstanceInspectorService $inspector,AuditService $audit){$result=$inspector->inspect($instance);$audit->record('inspect_instance','Inspección de instancia ejecutada.',$instance,['success'=>$result['success'],'schema_status'=>$result['schema_status'],'duration_ms'=>$result['duration_ms']]);return back()->with($result['success']?'success':'error',$result['success']?'Información de la instancia actualizada.':'No fue posible inspeccionar la instancia.');} }
